INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',133,'{"_type":"chat:Message","id":"8641420749:251","threadId":"telegram:8641420749","text":"1. Compte courant clement 9000€\n2. Deposito flash, toujours present mais ne fructifie pas, c’est comme un compte courant presque. Je peux le sortir des maintenant : 38500€\n3. 138,90 Le trf mensuel vers parents soge s’arrêtera fin décembre 2026, c’est un petit emprunt que je leur ai fait pour l’achat de notre voiture il y a quelques annee. Jusqu’à la fin 2026\n4.Tu n’as pas le compte perso de Lola mais tu devrais considerer qu’elle depense 500€/mois en depense perso\n5. None, mais j’ai un PEL en France avec 29827€ à 2% sur lequel mes parents virent 45€ par mois\n6. Tu fais reference a quoi ?\n7. Status residents permanents au Portugal, IRS Jovem, mariés, 3 enfants","formatted":{"type":"root","children":[{"type":"list","ordered":true,"start":1,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Compte courant clement 9000€","position":{"start":{"line":1,"column":4,"offset":3},"end":{"line":1,"column":32,"offset":31}}}],"position":{"start":{"line":1,"column":4,"offset":3},"end":{"line":1,"column":32,"offset":31}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":32,"offset":31}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Deposito flash, toujours present mais ne fructifie pas, c’est comme un compte courant presque. Je peux le sortir des maintenant : 38500€","position":{"start":{"line":2,"column":4,"offset":35},"end":{"line":2,"column":140,"offset":171}}}],"position":{"start":{"line":2,"column":4,"offset":35},"end":{"line":2,"column":140,"offset":171}}}],"position":{"start":{"line":2,"column":1,"offset":32},"end":{"line":2,"column":140,"offset":171}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type"