INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',140,'{"_type":"chat:Message","id":"8641420749:271","threadId":"telegram:8641420749","text":"7. Les 45€ que mes parents mettent tous les mois (gratuit pout moi) ca fait un taux fictif de combien combine avec les 2%\n5. Effectivement il faut vraiment evaluer de manière precise l’idee pour la RP","formatted":{"type":"root","children":[{"type":"list","ordered":true,"start":7,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Les 45€ que mes parents mettent tous les mois (gratuit pout moi) ca fait un taux fictif de combien combine avec les 2%","position":{"start":{"line":1,"column":4,"offset":3},"end":{"line":1,"column":122,"offset":121}}}],"position":{"start":{"line":1,"column":4,"offset":3},"end":{"line":1,"column":122,"offset":121}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":122,"offset":121}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Effectivement il faut vraiment evaluer de manière precise l’idee pour la RP","position":{"start":{"line":2,"column":4,"offset":125},"end":{"line":2,"column":79,"offset":200}}}],"position":{"start":{"line":2,"column":4,"offset":125},"end":{"line":2,"column":79,"offset":200}}}],"position":{"start":{"line":2,"column":1,"offset":122},"end":{"line":2,"column":79,"offset":200}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":79,"offset":200}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":79,"offset":200}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-22T17:34:39.000Z","edited":false},"attachments":[],"isMention":false}',1780076077695);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',141,'{"_type":"chat:Message","id":"8641420749:273","threadId":"telegram:8641420749","text":"- horizon achat dans 5 ans, pour l’instant on veut profiter de notre appart’ duplex de 130m2 avec 2 terrasses d’un total de 30m2 en plein principe real pour lequel on ne payer que 1200€ de loyer.\n- ville Lisboa ou Madrid dans des quartiers qui nous plaisent\n- surface tu en penses quoi pour une famille avec 3 enfants. On voudra au moins 3 chambres et 1 ou 2 bureau/atelier. Avec un espace extérieur aussi (mais pas forcement maison)\n- credit is the tool to get richer, isn’t it?","formatted":{"type":"root","children":[{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"horizon achat dans 5 ans, pour l’instant on veut profiter de notre appart’ duplex de 130m2 avec 2 terrasses d’un total de 30m2 en plein principe real pour lequel on ne payer que 1200€ de loyer.","position":{"start":{"line":1,"column":3,"offset":2},"end":{"line":1,"column":196,"offset":195}}}],"position":{"start":{"line":1,"column":3,"offset":2},"end":{"line":1,"column":196,"offset":195}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":196,"offset":195}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"ville Lisboa ou Madrid dans des quartiers qui nous plaisent","position":{"start":{"line":2,"column":3,"offset":198},"end":{"line":2,"column":62,"offset":257}}}],"position":{"start":{"line":2,"column":3,"offset":198},"end":{"line":2,"column":62,"offset":257}}}],"position":{"start":{"line":2,"column":1,"offset":196},"end":{"line":2,"column":62,"offset":257}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"surface tu en penses quoi pour une famille avec 3 enfants. On voudra au moins 3 chambres et 1 ou 2 bureau/atelier. Avec un espace extérieur aussi (mais pas forcement maison)","position":{"start":{"line":3,"column":3,"offset":260},"end":{"line":3,"column":176,"offset":433}}}],"position":{"start":{"line":3,"column":3,"offset":260},"end":{"line":3,"column":176,"offset":433}}}],"position":{"start":{"line":3,"column":1,"offset":258},"end":{"line":3,"column":176,"offset":433}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"credit is the tool to get richer, isn’t it?","position":{"start":{"line":4,"column":3,"offset":436},"end":{"line":4,"column":46,"offset":479}}}],"position":{"start":{"line":4,"column":3,"offset":436},"end":{"line":4,"column":46,"offset":479}}}],"position":{"start":{"line":4,"column":1,"offset":434},"end":{"line":4,"column":46,"offset":479}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":46,"offset":479}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":46,"offset":479}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-22T17:40:27.000Z","edited":false},"attachments":[],"isMention":false}',1780076425264);
