INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',143,'{"_type":"chat:Message","id":"8641420749:277","threadId":"telegram:8641420749","text":"Je ne pense pas qu’il faut penser un budget cible, plutot faire une estimation de la dream house en fonction des characteristics qu’on a defini, du cout actuel et du cout estime dans 5 ans.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je ne pense pas qu’il faut penser un budget cible, plutot faire une estimation de la dream house en fonction des characteristics qu’on a defini, du cout actuel et du cout estime dans 5 ans.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":190,"offset":189}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":190,"offset":189}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":190,"offset":189}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-22T17:59:54.000Z","edited":false},"attachments":[],"isMention":false}',1780077594343);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',144,'{"_type":"chat:Message","id":"8641420749:280","threadId":"telegram:8641420749","text":"Aussi pour l’investissement temporaire pour 5 ans avant l’achat de la RP on ne veut pas tout mettre en ETF. On aimerait evaluer si faire un investissement locatif pourrait etre interessant. Par exemple a Lisbon’e une nouvelle loi vient de passer qui cap à 10% les taxes si le loyer mensuel d’un investissement locatif est inferieur a 2300€ (verifie). Ausdi on m’a dit que les T1 c’est le plus facile à louer.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Aussi pour l’investissement temporaire pour 5 ans avant l’achat de la RP on ne veut pas tout mettre en ETF. On aimerait evaluer si faire un investissement locatif pourrait etre interessant. Par exemple a Lisbon’e une nouvelle loi vient de passer qui cap à 10% les taxes si le loyer mensuel d’un investissement locatif est inferieur a 2300€ (verifie). Ausdi on m’a dit que les T1 c’est le plus facile à louer.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":409,"offset":408}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":409,"offset":408}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":409,"offset":408}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-22T18:03:53.000Z","edited":false},"attachments":[],"isMention":false}',1780077833270);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',145,'{"_type":"chat:Message","id":"8641420749:283","threadId":"telegram:8641420749","text":"Non tu n’as pas compris. \nA part la retraite de Lola et le cash de sécurité, tout le reste de notre bilan patrimonial est disponible pour recréer une stratégie complète aujourd’hui (y compris les 180000€ de Lola, mon PEL etc…). Le rapport doit clarifier la situation pour un expert en investissement financier et immobilier qui va proposer différentes strategies. \n\nCree le rapport complet","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Non tu n’as pas compris.\nA part la retraite de Lola et le cash de sécurité, tout le reste de notre bilan patrimonial est disponible pour recréer une stratégie complète aujourd’hui (y compris les 180000€ de Lola, mon PEL etc…). Le rapport doit clarifier la situation pour un expert en investissement financier et immobilier qui va proposer différentes strategies.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":338,"offset":363}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":339,"offset":364}}},{"type":"paragraph","children":[{"type":"text","value":"Cree le rapport complet","position":{"start":{"line":4,"column":1,"offset":366},"end":{"line":4,"column":24,"offset":389}}}],"position":{"start":{"line":4,"column":1,"offset":366},"end":{"line":4,"column":24,"offset":389}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":24,"offset":389}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-22T18:10:33.000Z","edited":false},"attachments":[],"isMention":false}',1780078231610);
