INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',150,'{"_type":"chat:Message","id":"8641420749:298","threadId":"telegram:8641420749","text":"Ok c’est une bonne base, enregistre le rapport. Mais avant cela, enleve toute mention de la dette de 138,90€ par mois à mes parent jusqu’à fin 2026. Vu que je n’ai pas optimisé ces liquidités, je vais leur faire un virement du montant total jusqu’à fin 2026 et comme ça je peux l’oublier","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ok c’est une bonne base, enregistre le rapport. Mais avant cela, enleve toute mention de la dette de 138,90€ par mois à mes parent jusqu’à fin 2026. Vu que je n’ai pas optimisé ces liquidités, je vais leur faire un virement du montant total jusqu’à fin 2026 et comme ça je peux l’oublier","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":288,"offset":287}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":288,"offset":287}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":288,"offset":287}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-22T18:46:26.000Z","edited":false},"attachments":[],"isMention":false}',1780080385372);
