INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',152,'{"_type":"chat:Message","id":"8641420749:302","threadId":"telegram:8641420749","text":"Now i want to reschedule the recurrent tasks:\n- one task at 7pm on the day before the last working day of the month to remind me that i need to pay Branca and ask me how many hours she did this month so that you can calculate everything and send me her salary receipt\n- one task on the first weekday of the month to remind me to share with you the bank statements extracts from Activobank to track our expenses","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Now i want to reschedule the recurrent tasks:","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":46,"offset":45}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":46,"offset":45}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"one task at 7pm on the day before the last working day of the month to remind me that i need to pay Branca and ask me how many hours she did this month so that you can calculate everything and send me her salary receipt","position":{"start":{"line":2,"column":3,"offset":48},"end":{"line":2,"column":222,"offset":267}}}],"position":{"start":{"line":2,"column":3,"offset":48},"end":{"line":2,"column":222,"offset":267}}}],"position":{"start":{"line":2,"column":1,"offset":46},"end":{"line":2,"column":222,"offset":267}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"one task on the first weekday of the month to remind me to share with you the bank statements extracts from Activobank to track our expenses","position":{"start":{"line":3,"column":3,"offset":270},"end":{"line":3,"column":143,"offset":410}}}],"position":{"start":{"l