INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',155,'{"_type":"chat:Message","id":"8641420749:311","threadId":"telegram:8641420749","text":"Now play the role of the finance and real estate investment consultant that receives the report and build a strategy with several scenarios. Use Richard Rumelt for strategy definition and challenging it","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Now play the role of the finance and real estate investment consultant that receives the report and build a strategy with several scenarios. Use Richard Rumelt for strategy definition and challenging it","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":203,"offset":202}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":203,"offset":202}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":203,"offset":202}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-22T20:10:48.000Z","edited":false},"attachments":[],"isMention":false}',1780085445993);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',187,'{"_type":"chat:Message","id":"-5124234082:1734","threadId":"telegram:-5124234082","text":"Hello Pepa,\n\nSome updates:\n- We did not eat lunch at home today. We were both at the office.\n- The Equal Food Basket will arrive on Thursday, like every week.\n- Branka will only stay later on Thursday and we''re not sure yet if she will be able to cook so we''ll keep you posted for that.\n- Thursday night we''re not having dinner at home.\n\n\nThat''s it for now. We also have food in the inventory that my parents bought. I need to give you an update and send you some pictures. I will do that later.\n\nCan you give us a recipe for tonight? It''s the day that we''re coming back from the swimming pool so it should not be taking too long to cook.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Hello Pepa,","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":12,"offset":11}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":12,"offset":11}}},{"type":"paragraph","children":[{"type":"text","value":"Some updates:","position":{"start":{"line":3,"column":1,"offset":13},"end":{"line":3,"column":14,"offset":26}}}],"position":{"start":{"line":3,"column":1,"offset":13},"end":{"line":3,"column":14,"offset":26}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"We did not eat lunch at home today. We were both at the office.","position":{"start":{"line":4,"column":3,"offset":29},"end":{"line":4,"column":66,"offset":92}}}],"position":{"start":{"line":4,"column":3,"offset":29},"end":{"line":4,"column":66,"offset":92}}}],"position":{"start":{"line":4,"column":1,"offset":27},"end":{"line":4,"column":66,"offset":92}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"The Equal Food Basket will arrive on Thursday, like every week.","position":{"start":{"line":5,"column":3,"offset":95},"end":{"line":5,"column":66,"offset":158}}}],"position":{"start":{"line":5,"column":3,"offset":95},"end":{"line":5,"column":66,"offset":158}}}],"position":{"start":{"line":5,"column":1,"offset":93},"end":{"line":5,"column":66,"offset":158}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Branka will only stay later on Thursday and we''re not sure yet if she will be able to cook so we''ll keep you posted for that.","position":{"start":{"line":6,"column":3,"offset":161},"end":{"line":6,"column":128,"offset":286}}}],"position":{"start":{"line":6,"column":3,"offset":161},"end":{"line":6,"column":128,"offset":286}}}],"position":{"start":{"line":6,"column":1,"offset":159},"end":{"line":6,"column":128,"offset":286}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"Thursday night we''re not having dinner at home.","position":{"start":{"line":7,"column":3,"offset":289},"end":{"line":7,"column":50,"offset":336}}}],"position":{"start":{"line":7,"column":3,"offset":289},"end":{"line":7,"column":50,"offset":336}}}],"position":{"start":{"line":7,"column":1,"offset":287},"end":{"line":7,"column":50,"offset":336}}}],"position":{"start":{"line":4,"column":1,"offset":27},"end":{"line":7,"column":50,"offset":336}}},{"type":"paragraph","children":[{"type":"text","value":"That''s it for now. We also have food in the inventory that my parents bought. I need to give you an update and send you some pictures. I will do that later.","position":{"start":{"line":10,"column":1,"offset":339},"end":{"line":10,"column":157,"offset":495}}}],"position":{"start":{"line":10,"column":1,"offset":339},"end":{"line":10,"column":157,"offset":495}}},{"type":"paragraph","children":[{"type":"text","value":