INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',227,'{"_type":"chat:Message","id":"-5124234082:1845","threadId":"telegram:-5124234082","text":"We have this list of super authentic Italian sandwiches, and we want to identify which one we would like most, but also which one would be the easiest to do, meaning ingredients are not just super rare, but things that we have easily at hand or ingredients that we can buy pretty easily. Also let’s identify ingredients that we could try to always have at home that can be used in several of these sandwiches and can be kept for long. So analyze the list and let me know what you think. Then, once we''re done, we will see which one we add to the recipe list and keep track of.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"We have this list of super authentic Italian sandwiches, and we want to identify which one we would like most, but also which one would be the easiest to do, meaning ingredients are not just super rare, but things that we have easily at hand or ingredients that we can buy pretty easily. Also let’s identify ingredients that we could try to always have at home that can be used in several of these sandwiches and can be kept for long. So analyze the list and let me know what you think. Then, once we''re done, we will see which one we add to the recipe list and keep track of.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":577,"offset":576}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":577,"offset":576}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":577,"offset":576}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-05-28T22:08:59.000Z","edited":false},"attachments":[{"type":"image","size":237983,"width":1280,"height":960}],"isMention":false}',1780610936776);
