CREATE TABLE pending_sender_approvals (
        id                   TEXT PRIMARY KEY,
        messaging_group_id   TEXT NOT NULL REFERENCES messaging_groups(id),
        agent_group_id       TEXT NOT NULL REFERENCES agent_groups(id),
        sender_identity      TEXT NOT NULL,      -- namespaced user id (channel_type:handle)
        sender_name          TEXT,
        original_message     TEXT NOT NULL,      -- JSON serialized InboundEvent
        approver_user_id     TEXT NOT NULL,
        created_at           TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', options_json TEXT NOT NULL DEFAULT '[]',
        UNIQUE(messaging_group_id, sender_identity)
      );
CREATE TABLE pending_channel_approvals (
        messaging_group_id   TEXT PRIMARY KEY REFERENCES messaging_groups(id),
        agent_group_id       TEXT NOT NULL REFERENCES agent_groups(id),
                             -- The agent the approved wiring will target.
                             -- Picked at request time (currently: earliest
                             -- agent_group by created_at).
        original_message     TEXT NOT NULL,      -- JSON serialized InboundEvent
        approver_user_id     TEXT NOT NULL,
        created_at           TEXT NOT NULL
      , title TEXT NOT NULL DEFAULT '', options_json TEXT NOT NULL DEFAULT '[]');
CREATE UNIQUE INDEX idx_schema_version_name ON schema_version(name);
CREATE INDEX idx_user_roles_scope ON user_roles(agent_group_id, role);
CREATE INDEX idx_sessions_agent_group ON sessions(agent_group_id);
CREATE INDEX idx_sessions_lookup ON sessions(messaging_group_id, thread_id);
CREATE INDEX idx_pending_approvals_action_status
        ON pending_approvals(action, status);
CREATE INDEX idx_agent_dest_target ON agent_destinations(target_type, target_id);
CREATE INDEX idx_unregistered_senders_last_seen
        ON unregistered_senders(last_seen);
CREATE INDEX idx_pending_sender_approvals_mg
        ON pending_sender_approvals(messaging_group_id);
COMMIT;
